import{_ as d,l as c,o as e,c as s,v as o,p as i,x as r,d as l,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"边表与 CSR","description":"","frontmatter":{"title":"边表与 CSR","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/csr-graph.md","filePath":"cs/csr-graph.md","lastUpdated":1789023840000}'),h={name:"cs/csr-graph.md"};function f(m,a,S,C,_,u){const t=c("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="边表与-csr" tabindex="-1">边表与 CSR <a class="header-anchor" href="#边表与-csr" aria-label="Permalink to &quot;边表与 CSR&quot;">​</a></h1><div class="epigraph"><p>先把所有边摊成一条数组，再用 $n+1$ 个偏移标出每个顶点的一段；枚举邻居变成连续下标，没有指针。</p><footer>—— 据 Cormen, Leiserson, Rivest and Stein 对邻接表的数组化；稀疏矩阵压缩行存储的同一布局 整理</footer></div><p><a href="/cs/sparse-graph">上一课</a>把 \\(m\\ll n^2\\) 写成默认，并已经点名 CSR，却未把偏移数组与边表对照写完。<a href="/cs/adj-list-matrix">邻接表与邻接矩阵</a>的表仍可以是指针链。本课不重讲稀疏假设。缺口是三种连续表示：边表（pair 数组）、CSR（偏移 + 邻接下标）、以及有向图入边的 CSC。DAG 课要用「建完再检环」的静态图；CSR 正是静态默认。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>指针邻接表每条边一次堆分配，局部性差，增边方便。算法主干常是：<strong>先读完全部边，再跑 BFS</strong>。缺口不是新的图定义，而是布局：边表 <code>E[0..m)</code> 存 <code>(u,v)</code> 或 <code>(u,v,w)</code>，建图 \\(O(m)\\)，枚举 \\(u\\) 的出边要扫全部边除非排序。CSR：先计数每个出度，前缀和得到 <code>off[v]</code>，把邻居写入 <code>adj[off[v] .. off[v+1])</code>。枚举连续，\\(\\Theta(\\deg(v))\\) 步且吃 cache。</p><p>静态：CSR 改一条边要重建或预留空洞。动态增边回到向量-of-vectors 或链表。</p><p><span class="marginnote">压缩稀疏行来自稀疏矩阵 \\(A\\) 的行指针。无向图每条边在 <code>adj</code> 里出现两次，或边表存一次、CSR 建两份方向。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建 CSR：一遍数度，<code>off[0]=0</code>，<code>off[i+1]=off[i]+deg[i]</code>，再一遍填 <code>adj</code>（可用 <code>off</code> 副本当写指针）。问边 \\((u,v)\\)：在 \\(u\\) 的段里扫或对该段排序后二分；需要 \\(O(1)\\) 再另建散列。</p>',9)),(e(),i(p,null,{default:r(()=>[n(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20EL%5B%22%E8%BE%B9%E8%A1%A8%20m%20%E5%AF%B9%22%5D%20--%3E%20DEG%5B%22%E8%AE%A1%E5%87%BA%E5%BA%A6%22%5D%0A%20%20DEG%20--%3E%20OFF%5B%22%E5%89%8D%E7%BC%80%E5%92%8C%20off%5B0..n%5D%22%5D%0A%20%20OFF%20--%3E%20ADJ%5B%22%E8%BF%9E%E7%BB%AD%20adj%5B0..m)%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>CSC：按入边压缩，列偏移。需要入邻居时（拓扑 Kahn 的入度已另存）不必扫整张 CSR。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>空间 \\(\\Theta(n+m)\\) 与表相同，少指针开销。NUMA 上 <code>adj</code> 可按顶点区间切分。<a href="/cs/locality-principle">局部性原理</a>：BFS 按 CSR 扫出边，块预取有对象；指针表没有。这不改变 \\(\\Theta(n+m)\\)，改变常数——稀疏课已经预告。</p><p>平行边、自环：CSR 如实存放；算法自己决定是否跳过。加权：并行 <code>w[j]</code> 与 <code>adj[j]</code> 对齐。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入图稀疏化、不写动态 CSR 的对数重建。平面图下一课是拓扑性质（\\(m=O(n)\\) 的一类理由），不是另一种存储格式——平面图仍用 CSR。也不把矩阵 CSR 乘法写进主干。</p><p>后课默认：静态稀疏图用 CSR；边表当输入交换格式。无环有向是额外不变式，下一课 DAG。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>边表便于输入；CSR 用偏移把出边收成连续段。</li><li>静态、枚举友好；动态更新贵。</li><li>DAG 的无环约束下一课加在同一表示上。</li><li>出处：Cormen et al. 邻接表；稀疏矩阵 CSR 的标准布局。</li></ul>',9))])}const R=d(h,[["render",f]]);export{E as __pageData,R as default};
